// GuestLocalRun allow-list loader (game-free). The list is data (plugin/hooks/data/guest_local_run.json, generated by
// tools/gen_guest_local_run.py, deployed as nvcoop_guest_local_run.json next to nvcoop.dll):
//   {"scripts":[{"quest":"NVDLC02MQ00","script":"HonestHearts.esm:008A32"}, ...]}
// "script" is the quest's own script form as "plugin:hexLocalId". Entries that do not parse are skipped and counted.
#pragma once
#include <string>
#include <vector>

#include "fnvcoop/types.h"

namespace nvhooks {

struct GuestLocalRunList {
    std::vector<fnvcoop::FormRef> scripts;
    std::vector<std::string> quests;  // parallel to scripts (EDIDs, for logging)
    std::vector<std::string> reasons; // parallel to scripts; empty when the data file gives none
    int skipped = 0;                  // malformed entries
};

bool parseGuestLocalRun(const std::string& jsonText, GuestLocalRunList* out, std::string* err);

}  // namespace nvhooks
